// Die Instanzwerte kommen aus sub-einstellungen (Knoten davor) und werden
// in der Data Table pw_config gepflegt (n8n-Oberfläche, "Data Tables").
// HIER stehen nur die FACHLICHEN Einstellungen dieses Workflows: Fristen,
// Tag-Namen, Feldnamen.
const werte = $('Einstellungen holen').first().json;
const pw = (key) => {
  const v = werte[key];
  if (v === undefined || String(v).trim() === '') {
    throw new Error('pw_config: "' + key + '" fehlt oder ist leer; in der n8n-Oberfläche unter "Data Tables" eintragen.');
  }
  return v;
};
// admin_email: Alle Meldungen gehen an EINE Betreiber-Adresse, nicht an den
//   Besitzer des betroffenen Dokuments. Das ist keine Bequemlichkeit: der
//   n8n-Error-Trigger bekommt die Item-Daten des gescheiterten Laufs gar
//   nicht, er weiß also
//   nicht, um welches Dokument es ging, und damit auch nicht, wem es
//   gehört. Inhaltlich passt es ohnehin: hier stehen Stack Traces, nichts
//   Fachliches.
//
// instanz: steht im Mailbetreff. Ohne ihn sieht man einer Störungsmail nicht
//   an, von welcher Anlage sie kommt. Kommt aus pw_config, weil pro
//   Installation verschieden.
//
// DROSSELUNG: Logik im Node "Auswerten". Ohne sie erzeugt ein Massenimport
// bei ausgefallener Cloud-API eine Mail pro Dokument. Das ist fachliche
// Mechanik dieses Workflows und bleibt deshalb hier stehen:
//   schwellen: Beim wievielten gleichartigen Fehler innerhalb des Fensters
//     eine Mail rausgeht. [1,10,100,1000] heißt: 300 gleichartige Fehler
//     ergeben 3 Mails statt 300, die erste kommt sofort. Bewusst
//     logarithmisch statt "erste Mail, dann Ruhe": so transportiert die
//     Meldung auch die Schwere ("inzwischen 100x"), ohne dass es einen
//     zweiten Workflow mit Zeitplan bräuchte, der Zusammenfassungen
//     nachreicht.
//   max_mails_pro_fenster: harte Obergrenze über ALLE Signaturen hinweg,
//     falls viele verschiedene Fehler gleichzeitig auftreten. Danach kommt
//     eine "Fehlerflut"-Meldung und dann Ruhe bis zum Fensterende.
//   aufbewahrung_stunden: ab wann ein Vorfall aus dem Zustand fliegt. Ohne
//     das wüchse staticData unbegrenzt.
return [{
  json: {
    // ── aus der Data Table pw_config ──
    admin_email: pw('mail_betrieb'),
    absender:    pw('mail_absender'),
    instanz:     pw('instanz'),

    // ── fachlich, hier zu pflegen ──
    fenster_minuten: 60,
    schwellen: [1, 10, 100, 1000],
    max_mails_pro_fenster: 20,
    aufbewahrung_stunden: 24
  }
}];

// Normalisiert den Payload des Error Triggers und entscheidet, ob eine Mail
// rausgeht. Der Zustand für die Drosselung liegt in den Static Data dieses
// Workflows; das überlebt Läufe und braucht keinen externen Speicher.
const cfg = $json;
const roh = $('Error Trigger').first().json;

// ── 1. Zwei Payload-Formen auf dieselben Felder bringen ──────────────────
// Scheitert ein Trigger-Node beim AKTIVIEREN des Workflows, liefert n8n eine
// andere Struktur als bei einem Fehler während der Ausführung, unter
// anderem ohne Execution-ID und ohne URL.
const istTriggerFehler = !!roh.trigger;
const t = roh.trigger || {};
const e = roh.execution || {};

const d = istTriggerFehler
  ? {
      workflowName: roh.workflow?.name || 'Unbekannt',
      workflowId:   roh.workflow?.id   || 'Unbekannt',
      executionUrl: null,
      modus:        t.mode || 'trigger',
      node:         t.error?.node?.name || 'Trigger-Node',
      meldung:      t.error?.message || 'Keine Fehlermeldung verfügbar',
      stack:        t.error?.cause?.stack || t.error?.stack || 'Kein Stack Trace verfügbar',
      art:          'Trigger-Fehler (Workflow konnte nicht aktiviert werden)'
    }
  : {
      workflowName: roh.workflow?.name || 'Unbekannt',
      workflowId:   roh.workflow?.id   || 'Unbekannt',
      executionUrl: e.url || null,
      modus:        e.mode || 'unbekannt',
      node:         e.lastNodeExecuted || 'Unbekannt',
      meldung:      e.error?.message || 'Keine Fehlermeldung verfügbar',
      stack:        e.error?.stack || 'Kein Stack Trace verfügbar',
      art:          'Ausführungsfehler'
    };

// ── 2. Signatur ──────────────────────────────────────────────────────────
// Ziffern werden maskiert, weil Fehlermeldungen Dokument-IDs, Zeitstempel und
// Zeilennummern tragen. Ohne Maskierung wäre jeder Fehler eines Massenimports
// eine eigene Signatur und die Drosselung liefe ins Leere.
const signatur = [
  d.workflowId,
  d.node,
  String(d.meldung).replace(/\d+/g, '#').slice(0, 120)
].join(' | ');

// ── 3. Drosselung ────────────────────────────────────────────────────────
const s = $getWorkflowStaticData('global');
const jetzt = Date.now();
const fenster = cfg.fenster_minuten * 60 * 1000;
s.vorfaelle = s.vorfaelle || {};

for (const [k, alt] of Object.entries(s.vorfaelle)) {
  if (jetzt - (alt.zuletzt || 0) > cfg.aufbewahrung_stunden * 3600 * 1000) {
    delete s.vorfaelle[k];
  }
}

let v = s.vorfaelle[signatur];
if (!v || jetzt - v.beginn > fenster) {
  v = s.vorfaelle[signatur] = { beginn: jetzt, anzahl: 0 };
}
v.anzahl += 1;
v.zuletzt = jetzt;

if (!s.gesamt || jetzt - s.gesamt.beginn > fenster) {
  s.gesamt = { beginn: jetzt, mails: 0, unterdrueckt: 0, flutGemeldet: false };
}

let senden = false;
let grund = 'unterhalb der naechsten Schwelle';

if (cfg.schwellen.includes(v.anzahl)) {
  if (s.gesamt.mails < cfg.max_mails_pro_fenster) {
    senden = true;
    grund = 'schwelle';
    s.gesamt.mails += 1;
  } else if (!s.gesamt.flutGemeldet) {
    senden = true;
    grund = 'flut';
    s.gesamt.flutGemeldet = true;
    s.gesamt.mails += 1;
  }
}
if (!senden) s.gesamt.unterdrueckt += 1;

// ── 4. Mail bauen ────────────────────────────────────────────────────────
const zeit = new Date().toLocaleString('de-DE', { timeZone: 'Europe/Berlin' });
const esc = (x) => String(x ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

let betreff;
if (grund === 'flut') {
  betreff = '[' + cfg.instanz + '] Fehlerflut, weitere Meldungen werden unterdrückt';
} else if (v.anzahl === 1) {
  betreff = '[' + cfg.instanz + '] Störung: ' + d.workflowName;
} else {
  betreff = '[' + cfg.instanz + '] Störung (inzwischen ' + v.anzahl + 'x): ' + d.workflowName;
}

let hinweis = '';
if (grund === 'flut') {
  hinweis = '<p style="margin:0;font-size:14px;color:#8a3b00;">In diesem Zeitfenster wurden '
    + 'bereits ' + cfg.max_mails_pro_fenster + ' Fehlermails verschickt. Weitere Meldungen '
    + 'werden unterdrückt; der vollständige Umfang ist in n8n unter "Executions" sichtbar.</p>';
} else if (v.anzahl > 1) {
  const seit = new Date(v.beginn).toLocaleTimeString('de-DE', { timeZone: 'Europe/Berlin' });
  hinweis = '<p style="margin:0;font-size:14px;color:#8a3b00;">Dieser Fehler ist seit ' + seit
    + ' bereits <strong>' + v.anzahl + '-mal</strong> aufgetreten. Gemeldet wird beim '
    + cfg.schwellen.join('., ') + '. Vorkommen.</p>';
}

const zeile = (k, wert) =>
  '<tr><td style="padding:8px 12px;border-bottom:1px solid #e2e8f0;color:#718096;'
  + 'font-weight:600;width:150px;vertical-align:top;">' + k + '</td>'
  + '<td style="padding:8px 12px;border-bottom:1px solid #e2e8f0;color:#2d3748;">'
  + wert + '</td></tr>';

const html = '<!DOCTYPE html><html><head><meta charset="utf-8"></head>'
  + '<body style="margin:0;padding:24px;background:#f4f5f7;'
  + 'font-family:-apple-system,Segoe UI,Roboto,Arial,sans-serif;">'
  + '<table role="presentation" width="640" cellpadding="0" cellspacing="0" '
  + 'style="background:#fff;border-radius:10px;overflow:hidden;">'
  + '<tr><td style="background:#1a1a2e;padding:20px 24px;color:#fff;font-size:18px;font-weight:700;">'
  + 'Automatische Fehlermeldung'
  + '<div style="color:#a0aec0;font-size:13px;font-weight:400;padding-top:4px;">'
  + esc(cfg.instanz) + ' &middot; ' + zeit + '</div></td></tr>'
  + '<tr><td style="padding:24px;">'
  + '<div style="background:#fff8f0;border-left:4px solid #ed8936;padding:16px 20px;'
  + 'border-radius:0 6px 6px 0;margin-bottom:20px;">'
  + '<p style="margin:0 0 8px 0;font-size:15px;font-weight:700;color:#c05621;">Was ist passiert?</p>'
  + '<p style="margin:0 0 8px 0;font-size:14px;color:#4a5568;line-height:1.6;">Der Ablauf '
  + '<strong>' + esc(d.workflowName) + '</strong> ist abgebrochen. Bereits abgelegte Dokumente '
  + 'sind dadurch nicht beschädigt, die betroffene Verarbeitung wurde aber nicht zu Ende '
  + 'geführt.</p>' + hinweis + '</div>'
  + '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" '
  + 'style="background:#f7fafc;border:1px solid #e2e8f0;border-radius:6px;font-size:13px;">'
  + zeile('Ablauf', esc(d.workflowName))
  + zeile('Fehlerhafter Node', '<strong>' + esc(d.node) + '</strong>')
  + zeile('Fehlerart', esc(d.art))
  + zeile('Meldung', '<span style="color:#c53030;font-family:monospace;">' + esc(d.meldung) + '</span>')
  + zeile('Auslöser', esc(d.modus))
  + zeile('Workflow-ID', '<code>' + esc(d.workflowId) + '</code>')
  + zeile('Execution', d.executionUrl
      ? '<a href="' + esc(d.executionUrl) + '" style="color:#3182ce;">In n8n öffnen &rarr;</a>'
      : '<span style="color:#a0aec0;">nicht verfügbar (Trigger-Fehler)</span>')
  + '</table>'
  + '<p style="font-size:12px;color:#718096;margin:16px 0 6px 0;font-weight:600;">Stack Trace</p>'
  + '<pre style="margin:0;padding:12px;background:#1a1a2e;color:#a0aec0;border-radius:6px;'
  + 'font-size:11px;line-height:1.5;white-space:pre-wrap;word-break:break-all;">'
  + esc(d.stack) + '</pre>'
  + '</td></tr>'
  + '<tr><td style="padding:14px 24px;background:#f7fafc;border-top:1px solid #e2e8f0;'
  + 'font-size:11px;color:#a0aec0;">Erzeugt von <strong>fehler-melden</strong>. Empfänger ist '
  + 'die Betreiber-Adresse aus dem Konfigurations-Node, nicht der Besitzer des Dokuments.'
  + '</td></tr></table></body></html>';

return [{
  json: {
    senden,
    grund,
    signatur,
    anzahl: v.anzahl,
    unterdrueckt_im_fenster: s.gesamt.unterdrueckt,
    toEmail: cfg.admin_email,
    fromEmail: cfg.absender,
    subject: betreff,
    html
  }
}];
